namespace{juce::Font uiFont(float s){return juce::Font(juce::FontOptions(juce::Font::getDefaultSansSerifFontName(),s,juce::Font::plain));}void text(juce::Graphics&g,const juce::String&s,juce::Rectangle<float>r,float z,juce::Colour c,int a=juce::Justification::centred){g.setFont(uiFont(z));g.setColour(c);g.drawText(s,r,a);}void stroke(juce::Graphics&g,const juce::Path&p,juce::Colour c,float w){g.setColour(c);g.strokePath(p,juce::PathStrokeType(w,juce::PathStrokeType::curved,juce::PathStrokeType::rounded));}}
juce::Colour CloudyLook::pick(juce::uint32 n,juce::uint32 d,juce::uint32 w)const{return juce::Colour(theme==CloudyTheme::Neon?n:(theme==CloudyTheme::SolidDark?d:w));}juce::Colour CloudyLook::ink()const{return pick(0xffdce5fc,0xfff0f0f0,0xff242527);}juce::Colour CloudyLook::muted()const{return pick(0xff97a6c2,0xffa7a7a7,0xff6b6c70);}juce::Font CloudyLook::getTextButtonFont(juce::TextButton&,int){return uiFont(15);}void CloudyLook::drawButtonBackground(juce::Graphics&g,juce::Button&,const juce::Colour&,bool h,bool){auto r=g.getClipBounds().toFloat().reduced(2);g.setColour(pick(h?0xff26354c:0xff172130,h?0xff3b3b3b:0xff292929,h?0xffffffff:0xfff4f4f4));g.fillRoundedRectangle(r,9);g.setColour(pick(0xff34445b,0xff555555,0xffc2c3c6));g.drawRoundedRectangle(r,9,.8f);}void CloudyLook::drawButtonText(juce::Graphics&g,juce::TextButton&b,bool,bool){auto r=b.getLocalBounds().toFloat();auto c=r.getCentre();float s=juce::jmin(r.getWidth(),r.getHeight())/40;juce::Path p;if(b.getButtonText()=="power"){p.addCentredArc(0,1,8,8,0,.65f,juce::MathConstants<float>::twoPi-.65f,true);p.startNewSubPath(0,-10);p.lineTo(0,-1);}else{for(int i=0;i<40;++i){float a=float(i)*juce::MathConstants<float>::twoPi/40-juce::MathConstants<float>::halfPi,rad=(i%4==1||i%4==2)?10:7.7f;juce::Point<float>pt(std::cos(a)*rad,std::sin(a)*rad);if(!i)p.startNewSubPath(pt);else p.lineTo(pt);}p.closeSubPath();}p.applyTransform(juce::AffineTransform::scale(s).translated(c.x,c.y));stroke(g,p,ink(),1.7f*s);if(b.getButtonText()!="power"){g.setColour(ink());g.drawEllipse(c.x-3.2f*s,c.y-3.2f*s,6.4f*s,6.4f*s,1.7f*s);}}
