Cloudy9AudioProcessorEditor::Cloudy9AudioProcessorEditor(Cloudy9AudioProcessor&p):AudioProcessorEditor(&p),processor(p){juce::PropertiesFile::Options o;o.applicationName="Cloudy9";o.filenameSuffix="settings";o.folderName="RainlineMusic";o.osxLibrarySubFolder="Application Support";preferences=std::make_unique<juce::PropertiesFile>(o);auto saved=preferences->getValue("cloudy9.ui.theme","neon");setTheme(saved=="solidDark"?CloudyTheme::SolidDark:(saved=="solidWhite"?CloudyTheme::SolidWhite:CloudyTheme::Neon),false);setLookAndFeel(&look);setOpaque(true);setResizable(true,true);setResizeLimits(720,477,1440,954);getConstrainer()->setFixedAspectRatio(960./636.);for(auto*c:std::initializer_list<juce::Component*>{&amount,&color,&output,&settingsButton,&bypassButton})addAndMakeVisible(c);amountAttachment=std::make_unique<SliderAttachment>(p.parameters,"amount",amount);colorAttachment=std::make_unique<SliderAttachment>(p.parameters,"color",color);outputAttachment=std::make_unique<SliderAttachment>(p.parameters,"outputGain",output);amount.setDoubleClickReturnValue(true,0);color.setDoubleClickReturnValue(true,0);output.setDoubleClickReturnValue(true,0);bypassButton.setClickingTogglesState(true);bypassAttachment=std::make_unique<juce::AudioProcessorValueTreeState::ButtonAttachment>(p.parameters,"bypass",bypassButton);settingsButton.onClick=[this]{showSettingsMenu();};int w=p.editorWidth.load();if(w<720||w>1440)w=preferences->getIntValue("cloudy9.ui.width",960);setSize(w,juce::roundToInt(w*636./960.));ready=true;startTimerHz(30);}Cloudy9AudioProcessorEditor::~Cloudy9AudioProcessorEditor(){stopTimer();saveSize();setLookAndFeel(nullptr);}void Cloudy9AudioProcessorEditor::saveSize(){if(!ready)return;processor.editorWidth.store(getWidth());preferences->setValue("cloudy9.ui.width",getWidth());preferences->saveIfNeeded();resizeStamp=0;}void Cloudy9AudioProcessorEditor::setTheme(CloudyTheme t,bool persist){look.theme=t;if(persist&&preferences){preferences->setValue("cloudy9.ui.theme",t==CloudyTheme::Neon?"neon":(t==CloudyTheme::SolidDark?"solidDark":"solidWhite"));preferences->saveIfNeeded();}repaint();for(auto*c:getChildren())c->repaint();}
void Cloudy9AudioProcessorEditor::showSettingsMenu(){juce::PopupMenu menu,themes,debug;themes.addItem(1,"Neon",true,look.theme==CloudyTheme::Neon);themes.addItem(2,"Solid Dark",true,look.theme==CloudyTheme::SolidDark);themes.addItem(3,"Solid White",true,look.theme==CloudyTheme::SolidWhite);int selected=2+juce::roundToInt(processor.parameters.getRawParameterValue("harmonic")->load());for(int h=2;h<=11;++h)debug.addItem(100+h,"H"+juce::String(h),true,selected==h);menu.addSubMenu("Theme",themes);menu.addSeparator();menu.addSubMenu("Debug harmonic",debug);auto safe=juce::Component::SafePointer<Cloudy9AudioProcessorEditor>(this);menu.showMenuAsync(juce::PopupMenu::Options().withTargetComponent(settingsButton),[safe](int id){if(!safe||!id)return;if(id==1)safe->setTheme(CloudyTheme::Neon);else if(id==2)safe->setTheme(CloudyTheme::SolidDark);else if(id==3)safe->setTheme(CloudyTheme::SolidWhite);else if(id>=102&&id<=111)if(auto*p=safe->processor.parameters.getParameter("harmonic")){p->beginChangeGesture();p->setValueNotifyingHost(float(id-102)/9);p->endChangeGesture();}});}
