void Cloudy9AudioProcessorEditor::captureBlurSnapshot(){if(capturingBlur||blurArea.isEmpty())return;capturingBlur=true;auto source=createComponentSnapshot(blurArea,true,1);capturingBlur=false;if(!source.isValid())return;int w=juce::jmax(16,source.getWidth()/6),h=juce::jmax(16,source.getHeight()/6);juce::Image small(juce::Image::ARGB,w,h,true),soft(juce::Image::ARGB,w,h,true);{juce::Graphics sg(small);sg.drawImage(source,juce::Rectangle<float>(0,0,float(w),float(h)),juce::RectanglePlacement::stretchToFit);}juce::ImageConvolutionKernel k(9);k.createGaussianBlur(2.2f);k.applyToImage(soft,small,small.getBounds());blurredSnapshot=soft;}void Cloudy9AudioProcessorEditor::paintOverChildren(juce::Graphics&g){if(capturingBlur||!bypassTarget||!blurredSnapshot.isValid())return;g.drawImage(blurredSnapshot,blurArea.toFloat(),juce::RectanglePlacement::stretchToFit);g.setColour((look.isDark()?juce::Colours::black:juce::Colours::white).withAlpha(.18f));g.fillRoundedRectangle(blurArea.toFloat(),12);auto r=blurArea.toFloat().translated(0,-blurArea.getHeight()*.05f);text(g,"BYPASSED",r,juce::jmax(34.f,float(getWidth())/18),look.isDark()?juce::Colours::white:juce::Colour(0xff202124));}void Cloudy9AudioProcessorEditor::timerCallback(){if(resizeStamp>0&&juce::Time::getMillisecondCounterHiRes()-resizeStamp>400)saveSize();bool target=processor.parameters.getRawParameterValue("bypass")->load()>.5f||processor.displayBypass.load();if(target!=bypassTarget){bypassTarget=target;amount.setEnabled(!target);color.setEnabled(!target);output.setEnabled(!target);if(target)captureBlurSnapshot();else blurredSnapshot={};}repaint();}
